print("EXPERIMENT_DATA_SCOPE :", EXPERIMENT_DATA_SCOPE)
print("SAMPLE_SELECTION_SEED :", SAMPLE_SELECTION_SEED)
print("SEEDS                 :", SEEDS)
print("ACTIVE_MODELS         :", ACTIVE_MODELS)
