# ------------------------------------------------------------
# 4. HDF5 string decoder
# ------------------------------------------------------------

def decode_probe_h5_value(
    value,
) -> str:

    if isinstance(
        value,
        bytes,
    ):

        return value.decode(
            "utf-8"
        )

    return str(
        value
    )


# ------------------------------------------------------------
# 5. Feature-key discovery
# ------------------------------------------------------------

def discover_probe_feature_keys(
    model_key: str,
):
    """
    Return the actual extracted VF/VT/QT datasets in the HDF5 file.
    """

    path = Path(
        feature_h5_path(
            model_key
        )
    )


    if not path.exists():

        raise FileNotFoundError(
            f"Feature HDF5 file does not exist for {model_key!r}:\n"
            f"{path}"
        )


    with h5py.File(
        path,
        "r",
    ) as h5:

        keys = sorted(
            [
                key
                for key in h5.keys()
                if (
                    key == "vf"
                    or key.startswith("vt_")
                    or key.startswith("qt_")
                )
            ]
        )


    return keys


# ------------------------------------------------------------
# 6. Read a feature matrix safely
# ------------------------------------------------------------

def read_probe_h5_feature_matrix(
    model_key: str,
    feature_key: str,
    split_frame: pd.DataFrame,
):
    """
    Read feature rows aligned by question_id.

    Labels are read from the supplied split dataframe, not from HDF5.
    """

    if not isinstance(
        split_frame,
        pd.DataFrame,
    ):

        raise TypeError(
            "split_frame must be a pandas DataFrame."
        )


    required_columns = {
        "question_id",
        "label",
    }


    missing = (
        required_columns
        - set(
            split_frame.columns
        )
    )


    if missing:

        raise RuntimeError(
            f"Split dataframe is missing required columns: "
            f"{sorted(missing)}"
        )


    qids_requested = (
        split_frame[
            "question_id"
        ]
        .astype(str)
        .tolist()
    )


    if not qids_requested:

        raise RuntimeError(
            f"{model_key} / {feature_key}: empty split."
        )


    with h5py.File(
        feature_h5_path(
            model_key
        ),
        "r",
    ) as h5:

        if (
            "question_id"
            not in h5
        ):

            raise RuntimeError(
                f"{model_key}: HDF5 has no question_id dataset."
            )


        if (
            feature_key
            not in h5
        ):

            raise KeyError(
                f"{model_key}: feature dataset "
                f"{feature_key!r} does not exist."
            )


        qids_h5 = [
            decode_probe_h5_value(
                value
            )
            for value in h5[
                "question_id"
            ][:]
        ]


        qid_to_idx = {
            qid: index
            for index, qid in enumerate(
                qids_h5
            )
        }


        missing_qids = [
            qid
            for qid in qids_requested
            if qid not in qid_to_idx
        ]


        if missing_qids:

            raise RuntimeError(
                f"{model_key} / {feature_key}: "
                f"{len(missing_qids)} requested question IDs "
                "are absent from the feature file.\n"
                f"Examples: {missing_qids[:20]}"
            )


        indices = [
            qid_to_idx[
                qid
            ]
            for qid in qids_requested
        ]


        # HDF5 advanced indexing is most robust when indexes are sorted.
        # We read rows individually through sorted indices and restore the
        # requested order afterward.
        order = np.argsort(
            np.asarray(
                indices
            )
        )


        sorted_indices = [
            indices[
                i
            ]
            for i in order
        ]


        sorted_rows = np.asarray(
            h5[
                feature_key
            ][sorted_indices, :],
            dtype=np.float32,
        )


        inverse_order = np.argsort(
            order
        )


        X = (
            sorted_rows[
                inverse_order
            ]
        )


    y = (
        pd.to_numeric(
            split_frame[
                "label"
            ],
            errors="raise",
        )
        .astype(np.int64)
        .to_numpy()
    )


    if X.ndim != 2:

        raise RuntimeError(
            f"{model_key} / {feature_key}: "
            f"expected X with rank 2, got shape={X.shape}"
        )


    if len(X) != len(y):

        raise RuntimeError(
            f"{model_key} / {feature_key}: "
            f"X/y length mismatch: {len(X)} vs {len(y)}"
        )


    if not np.isfinite(
        X
    ).all():

        raise ValueError(
            f"{model_key} / {feature_key}: "
            "NaN/Inf detected in extracted features."
        )


    if not np.isin(
        y,
        [0, 1],
    ).all():

        raise ValueError(
            f"{model_key}: labels must contain only 0/1."
        )


    return X, y


# ------------------------------------------------------------
# 7. Safely identify completed feature IDs
# ------------------------------------------------------------

def get_complete_feature_ids(
    model_key: str,
):
    """
    Return only question IDs whose HDF5 status is complete.
    """

    path = Path(
        feature_h5_path(
            model_key
        )
    )


    if not path.exists():

        raise FileNotFoundError(
            path
        )


    with h5py.File(
        path,
        "r",
    ) as h5:

        if "question_id" not in h5:

            raise RuntimeError(
                f"{model_key}: HDF5 has no question_id dataset."
            )


        if "status" not in h5:

            raise RuntimeError(
                f"{model_key}: HDF5 has no status dataset."
            )


        qids = [
            decode_probe_h5_value(
                value
            )
            for value in h5[
                "question_id"
            ][:]
        ]


        statuses = [
            decode_probe_h5_value(
                value
            )
            for value in h5[
                "status"
            ][:]
        ]


    if len(qids) != len(statuses):

        raise RuntimeError(
            f"{model_key}: question_id/status length mismatch."
        )


    return {
        qid
        for qid, status in zip(
            qids,
            statuses,
        )
        if status == "complete"
    }


# ------------------------------------------------------------
# 8. Validate a supervised split
# ------------------------------------------------------------

def validate_supervised_split(
    model_key: str,
):
    """
    Return train/val/test frames only when genuine labels and a valid split
    exist.

    Returns:
        parts or None
        reason
    """

    # --------------------------------------------------------
    # No model-specific labels
    # --------------------------------------------------------

    if not HAS_MODEL_DF:

        return (
            None,
            "model_df is unavailable; no reviewed-label dataframe exists.",
        )


    if model_key not in model_df:

        return (
            None,
            f"model_df[{model_key!r}] is unavailable because "
            "no reviewed-label dataframe was loaded for this model.",
        )


    labeled_frame = model_df[
        model_key
    ]


    if not isinstance(
        labeled_frame,
        pd.DataFrame,
    ):

        return (
            None,
            f"model_df[{model_key!r}] is not a DataFrame.",
        )


    required_label_columns = {
        "question_id",
        "label",
    }


    missing_columns = (
        required_label_columns
        - set(
            labeled_frame.columns
        )
    )


    if missing_columns:

        return (
            None,
            f"Reviewed-label dataframe is missing columns: "
            f"{sorted(missing_columns)}",
        )


    # --------------------------------------------------------
    # Existing grouped split
    # --------------------------------------------------------

    if (
        HAS_SPLITS
        and model_key in splits
    ):

        parts = splits[
            model_key
        ]


        if not isinstance(
            parts,
            dict,
        ):

            return (
                None,
                "Existing split object is not a dictionary.",
            )


        required_parts = {
            "train",
            "val",
            "test",
        }


        missing_parts = (
            required_parts
            - set(
                parts.keys()
            )
        )


        if missing_parts:

            return (
                None,
                f"Existing split is missing: {sorted(missing_parts)}",
            )


        train = parts[
            "train"
        ].copy()


        val = parts[
            "val"
        ].copy()


        test = parts[
            "test"
        ].copy()


    # --------------------------------------------------------
    # Split missing but labels exist
    # --------------------------------------------------------
    #
    # Recreate it using the notebook's canonical grouped splitter.
    # This is safe because the split is derived from labels and group_id,
    # never from the test predictions.
    # --------------------------------------------------------

    else:

        if (
            "choose_grouped_split"
            not in globals()
        ):

            return (
                None,
                "No valid splits exist and choose_grouped_split() "
                "is unavailable.",
            )


        try:

            train, val, test = (
                choose_grouped_split(
                    labeled_frame.copy().reset_index(
                        drop=True
                    ),
                    seed=(
                        SEEDS[0]
                        if HAS_SEEDS
                        else 42
                    ),
                )
            )

        except Exception as exc:

            return (
                None,
                "Could not construct a grouped supervised split: "
                f"{type(exc).__name__}: {exc}",
            )


    # --------------------------------------------------------
    # Normalize IDs and labels
    # --------------------------------------------------------

    normalized = {}


    for name, frame in [
        (
            "train",
            train,
        ),
        (
            "val",
            val,
        ),
        (
            "test",
            test,
        ),
    ]:

        if not isinstance(
            frame,
            pd.DataFrame,
        ):

            return (
                None,
                f"{name} split is not a DataFrame.",
            )


        if (
            "question_id"
            not in frame.columns
            or "label"
            not in frame.columns
        ):

            return (
                None,
                f"{name} split lacks question_id or label.",
            )


        frame = frame.copy()


        frame[
            "question_id"
        ] = (
            frame[
                "question_id"
            ]
            .astype(str)
        )


        frame[
            "label"
        ] = (
            pd.to_numeric(
                frame[
                    "label"
                ],
                errors="raise",
            )
            .astype(np.int64)
        )


        if not np.isin(
            frame[
                "label"
            ].to_numpy(),
            [0, 1],
        ).all():

            return (
                None,
                f"{name} split contains labels outside {0,1}.",
            )


        normalized[
            name
        ] = frame


    train = normalized[
        "train"
    ]


    val = normalized[
        "val"
    ]


    test = normalized[
        "test"
    ]


    # --------------------------------------------------------
    # Verify no split overlap by question ID
    # --------------------------------------------------------

    train_ids = set(
        train[
            "question_id"
        ]
    )


    val_ids = set(
        val[
            "question_id"
        ]
    )


    test_ids = set(
        test[
            "question_id"
        ]
    )


    if not train_ids.isdisjoint(
        val_ids
    ):

        return (
            None,
            "Train/validation question-ID overlap detected.",
        )


    if not train_ids.isdisjoint(
        test_ids
    ):

        return (
            None,
            "Train/test question-ID overlap detected.",
        )


    if not val_ids.isdisjoint(
        test_ids
    ):

        return (
            None,
            "Validation/test question-ID overlap detected.",
        )


    return (
        {
            "train":
                train,

            "val":
                val,

            "test":
                test,
        },
        None,
    )


# ------------------------------------------------------------
# 9. Fit scaler on TRAIN ONLY
# ------------------------------------------------------------

def standardize_train_only(
    X_train,
    X_val,
    X_test,
):
    """
    Fit feature standardization only on the training partition.
    """

    X_train = np.asarray(
        X_train,
        dtype=np.float32,
    )


    X_val = np.asarray(
        X_val,
        dtype=np.float32,
    )


    X_test = np.asarray(
        X_test,
        dtype=np.float32,
    )


    if X_train.ndim != 2:

        raise ValueError(
            f"X_train must be 2-D, got {X_train.shape}"
        )


    mean = (
        X_train
        .mean(
            axis=0,
            keepdims=True,
        )
    )


    std = (
        X_train
        .std(
            axis=0,
            keepdims=True,
        )
    )


    # Protect constant dimensions without changing the actual features.
    std = np.where(
        std < 1e-6,
        1e-6,
        std,
    )


    return (
        (X_train - mean) / std,
        (X_val - mean) / std,
        (X_test - mean) / std,
        mean,
        std,
    )


# ------------------------------------------------------------
# 10. Model probability helper
# ------------------------------------------------------------

def get_probe_probabilities(
    probe,
    X,
):
    """
    Return probability of hallucination (positive class = 1).
    """

    if hasattr(
        probe,
        "predict_proba",
    ):

        probabilities = probe.predict_proba(
            X
        )[:, 1]


    else:

        device = next(
            probe.parameters()
        ).device


        X_tensor = (
            torch.from_numpy(
                np.asarray(
                    X,
                    dtype=np.float32,
                )
            )
            .to(
                device
            )
        )


        probe.eval()


        with torch.inference_mode():

            logits = probe(
                X_tensor
            )


            probabilities = (
                torch.sigmoid(
                    logits
                )
                .detach()
                .cpu()
                .numpy()
            )


    probabilities = np.asarray(
        probabilities,
        dtype=np.float64,
    )


    if not np.isfinite(
        probabilities
    ).all():

        raise ValueError(
            "Probe returned non-finite probabilities."
        )


    probabilities = np.clip(
        probabilities,
        0.0,
        1.0,
    )


    return probabilities


# ------------------------------------------------------------
# 11. Run one model
# ------------------------------------------------------------

def train_and_evaluate_model(
    model_key: str,
):
    """
    Train/evaluate probes for one model.

    Returns an empty DataFrame when supervised training is blocked.
    """

    # --------------------------------------------------------
    # Basic feature-file check
    # --------------------------------------------------------

    feature_path = Path(
        feature_h5_path(
            model_key
        )
    )


    if not feature_path.exists():

        raise FileNotFoundError(
            f"Feature file for {model_key!r} does not exist:\n"
            f"{feature_path}"
        )


    # --------------------------------------------------------
    # Require real reviewed labels
    # --------------------------------------------------------

    split_parts, split_block_reason = (
        validate_supervised_split(
            model_key
        )
    )


    if split_parts is None:

        print(
            "\n"
            + "-" * 82
        )


        print(
            f"PROBE TRAINING BLOCKED: {model_key}"
        )


        print(
            "-" * 82
        )


        print(
            "Reason:",
            split_block_reason
        )


        print(
            "Feature extraction may still be valid."
        )


        print(
            "No hallucination labels will be inferred or fabricated."
        )


        blocked_path = (
            LOGS_DIR
            / f"{model_key}_probe_training_blocked.json"
        )


        blocked_record = {

            "model":
                model_key,

            "status":
                "BLOCKED",

            "reason":
                split_block_reason,

            "feature_path":
                str(
                    feature_path
                ),

            "created_at_utc":
                datetime.now(
                    timezone.utc
                ).isoformat(),
        }


        blocked_path.write_text(
            json.dumps(
                blocked_record,
                indent=2,
            ),
            encoding="utf-8",
        )


        # Return a well-formed empty result rather than raising a misleading
        # KeyError such as splits["smolvlm2"].
        return pd.DataFrame(
            [
                blocked_record
            ]
        )


    train = split_parts[
        "train"
    ].copy()


    val = split_parts[
        "val"
    ].copy()


    test = split_parts[
        "test"
    ].copy()


    # --------------------------------------------------------
    # Required split size
    # --------------------------------------------------------

    if min(
        len(train),
        len(val),
        len(test),
    ) < 4:

        reason = (
            "Each split must contain at least 4 rows before probe "
            "training is attempted."
        )


        print(
            f"[{model_key}] PROBE TRAINING BLOCKED: {reason}"
        )


        return pd.DataFrame(
            [
                {
                    "model":
                        model_key,

                    "status":
                        "BLOCKED",

                    "reason":
                        reason,

                    "train_rows":
                        len(train),

                    "val_rows":
                        len(val),

                    "test_rows":
                        len(test),
                }
            ]
        )


    # --------------------------------------------------------
    # Completed feature IDs
    # --------------------------------------------------------

    complete_qids = get_complete_feature_ids(
        model_key
    )


    # --------------------------------------------------------
    # Keep only samples with actual extracted features
    # --------------------------------------------------------

    train = train[
        train[
            "question_id"
        ].isin(
            complete_qids
        )
    ].copy()


    val = val[
        val[
            "question_id"
        ].isin(
            complete_qids
        )
    ].copy()


    test = test[
        test[
            "question_id"
        ].isin(
            complete_qids
        )
    ].copy()


    print(
        "\n"
        + "-" * 82
    )


    print(
        f"MODEL: {model_key}"
    )


    print(
        "-" * 82
    )


    print(
        "Labeled split rows before feature filter:",
        {
            "train":
                len(
                    split_parts[
                        "train"
                    ]
                ),

            "val":
                len(
                    split_parts[
                        "val"
                    ]
                ),

            "test":
                len(
                    split_parts[
                        "test"
                    ]
                ),
        }
    )


    print(
        "Complete-feature split rows:",
        {
            "train":
                len(train),

            "val":
                len(val),

            "test":
                len(test),
        }
    )


    # --------------------------------------------------------
    # Smoke-test protection
    # --------------------------------------------------------
    #
    # A smoke extraction of 32 samples usually cannot populate a valid
    # train/validation/test partition after the grouped split has been
    # created on the full labeled benchmark.
    #
    # Do not manufacture a new random split using the test features.
    # --------------------------------------------------------

    if min(
        len(train),
        len(val),
        len(test),
    ) < 4:

        reason = (
            "Too few completed labeled samples remain in at least one "
            "partition after intersecting the supervised split with "
            "the extracted feature IDs. Run a larger feature extraction "
            "with genuine reviewed labels before training."
        )


        print(
            f"[{model_key}] PROBE TRAINING BLOCKED:"
        )


        print(
            reason
        )


        blocked_path = (
            LOGS_DIR
            / f"{model_key}_probe_training_blocked.json"
        )


        blocked_record = {

            "model":
                model_key,

            "status":
                "BLOCKED",

            "reason":
                reason,

            "train_rows":
                len(train),

            "val_rows":
                len(val),

            "test_rows":
                len(test),

            "complete_feature_ids":
                len(complete_qids),

            "created_at_utc":
                datetime.now(
                    timezone.utc
                ).isoformat(),
        }


        blocked_path.write_text(
            json.dumps(
                blocked_record,
                indent=2,
            ),
            encoding="utf-8",
        )


        return pd.DataFrame(
            [
                blocked_record
            ]
        )


    # --------------------------------------------------------
    # Ensure both classes occur in all partitions
    # --------------------------------------------------------

    partition_class_counts = {

        "train":
            train[
                "label"
            ].value_counts(
                sort=False
            ).to_dict(),

        "val":
            val[
                "label"
            ].value_counts(
                sort=False
            ).to_dict(),

        "test":
            test[
                "label"
            ].value_counts(
                sort=False
            ).to_dict(),
    }


    for split_name, frame in [
        (
            "train",
            train,
        ),
        (
            "val",
            val,
        ),
        (
            "test",
            test,
        ),
    ]:

        if frame[
            "label"
        ].nunique() < 2:

            reason = (
                f"{split_name} partition contains only one class."
            )


            print(
                f"[{model_key}] PROBE TRAINING BLOCKED: {reason}"
            )


            return pd.DataFrame(
                [
                    {
                        "model":
                            model_key,

                        "status":
                            "BLOCKED",

                        "reason":
                            reason,

                        "class_counts":
                            partition_class_counts,
                    }
                ]
            )


    # --------------------------------------------------------
    # Feature keys
    # --------------------------------------------------------

    feature_keys = discover_probe_feature_keys(
        model_key
    )


    if not feature_keys:

        raise RuntimeError(
            f"{model_key}: no VF/VT/QT features are available."
        )


    print(
        "Feature keys:",
        feature_keys,
    )


    all_rows = []


    # --------------------------------------------------------
    # Representation loop
    # --------------------------------------------------------

    for feature_key in tqdm(
        feature_keys,
        total=len(feature_keys),
        desc=f"{model_key} representations",
        unit="representation",
        leave=False,
    ):

        print(
            "\n"
            + "=" * 82
        )


        print(
            f"REPRESENTATION: {feature_key}"
        )


        print(
            "=" * 82
        )


        try:

            Xtr, ytr = (
                read_probe_h5_feature_matrix(
                    model_key,
                    feature_key,
                    train,
                )
            )


            Xva, yva = (
                read_probe_h5_feature_matrix(
                    model_key,
                    feature_key,
                    val,
                )
            )


            Xte, yte = (
                read_probe_h5_feature_matrix(
                    model_key,
                    feature_key,
                    test,
                )
            )


        except Exception as exc:

            print(
                f"[{model_key} / {feature_key}] "
                f"feature read failed: "
                f"{type(exc).__name__}: {exc}"
            )


            all_rows.append(
                {
                    "model":
                        model_key,

                    "representation":
                        feature_key,

                    "probe":
                        "unavailable",

                    "seed":
                        np.nan,

                    "split":
                        "none",

                    "status":
                        "FAILED",

                    "error":
                        f"{type(exc).__name__}: {exc}",
                }
            )


            continue


        # ----------------------------------------------------
        # Train-only standardization
        # ----------------------------------------------------

        (
            Xtr_s,
            Xva_s,
            Xte_s,
            train_mean,
            train_std,
        ) = standardize_train_only(
            Xtr,
            Xva,
            Xte,
        )


        print(
            "Feature dimension:",
            Xtr.shape[1],
        )


        print(
            "Shapes:",
            {
                "train":
                    Xtr_s.shape,

                "val":
                    Xva_s.shape,

                "test":
                    Xte_s.shape,
            }
        )


        # ----------------------------------------------------
        # Determine seeds
        # ----------------------------------------------------

        if HAS_SEEDS:

            active_seeds = [
                int(seed)
                for seed in SEEDS
            ]

        else:

            active_seeds = [
                42
            ]


        # ----------------------------------------------------
        # Each seed
        # ----------------------------------------------------

        for seed in tqdm(
            active_seeds,
            total=len(active_seeds),
            desc=f"{model_key}/{feature_key} seeds",
            unit="seed",
            leave=False,
        ):

            # ====================================================
            # LOGISTIC REGRESSION
            # ====================================================

            set_all_seeds(
                seed
            )


            try:

                logistic_model, logistic_weighting = fit_logistic_probe(
                    Xtr_s,
                    ytr,
                    seed,
                )


                val_prob = (
                    get_probe_probabilities(
                        logistic_model,
                        Xva_s,
                    )
                )


                val_threshold, threshold_rule = select_validation_threshold(
                    yva,
                    val_prob,
                )
                val_metrics = safe_binary_metrics(
                    yva,
                    val_prob,
                    threshold=val_threshold,
                )


                all_rows.append(
                    {
                        "model":
                            model_key,

                        "representation":
                            feature_key,

                        "probe":
                            "logistic",

                        "seed":
                            seed,

                        "split":
                            "validation",

                        "status":
                            "COMPLETED",

                        "selected_config":
                            "logistic_baseline",

                        "weighting_mode":
                            logistic_weighting["mode"],

                        "threshold_rule":
                            threshold_rule,

                        **val_metrics,
                    }
                )


                # ------------------------------------------------
                # Final logistic fit
                # ------------------------------------------------
                #
                # Test is untouched until this point.
                # The linear baseline has no validation-selected
                # hyperparameter other than its fixed configuration.
                # ------------------------------------------------

                # Final refit uses all allowed train + validation information
                # to estimate normalization statistics. The test set remains
                # completely untouched until final prediction.
                Xfit_raw_logistic = np.vstack(
                    [
                        Xtr,
                        Xva,
                    ]
                )

                yfit_logistic = np.concatenate(
                    [
                        ytr,
                        yva,
                    ]
                )

                (
                    Xfit_logistic,
                    _unused_val_refit_logistic,
                    Xte_logistic,
                    refit_mean_logistic,
                    refit_std_logistic,
                ) = standardize_train_only(
                    Xfit_raw_logistic,
                    Xfit_raw_logistic,
                    Xte,
                )

                final_logistic, final_logistic_weighting = (
                    fit_logistic_probe(
                        Xfit_logistic,
                        yfit_logistic,
                        seed,
                    )
                )

                test_prob = (
                    get_probe_probabilities(
                        final_logistic,
                        Xte_logistic,
                    )
                )


                test_metrics = safe_binary_metrics(
                    yte,
                    test_prob,
                    threshold=val_threshold,
                )


                all_rows.append(
                    {
                        "model":
                            model_key,

                        "representation":
                            feature_key,

                        "probe":
                            "logistic",

                        "seed":
                            seed,

                        "split":
                            "test",

                        "status":
                            "COMPLETED",

                        "selected_config":
                            "logistic_baseline",

                        "weighting_mode":
                            final_logistic_weighting["mode"],

                        "threshold_rule":
                            threshold_rule,

                        **test_metrics,
                    }
                )

                # Save logistic test probabilities so every reported probe can be
                # independently re-scored just like the MLP results.
                if bool(globals().get("SAVE_LOGISTIC_TEST_PREDICTIONS", True)):
                    logistic_prediction_df = pd.DataFrame(
                        {
                            "question_id": test["question_id"].astype(str).to_numpy(),
                            "image_name": (
                                test["image_name"].astype(str).to_numpy()
                                if "image_name" in test.columns
                                else ""
                            ),
                            "label": yte,
                            "probability": test_prob,
                            "threshold": float(val_threshold),
                            "prediction": (
                                test_prob >= float(val_threshold)
                            ).astype(int),
                            "model": model_key,
                            "representation": feature_key,
                            "probe": "logistic",
                            "seed": seed,
                            "selected_config": "logistic_baseline",
                            "selected": True,
                            "threshold_rule": threshold_rule,
                            "weighting_mode": final_logistic_weighting["mode"],
                        }
                    )

                    logistic_prediction_path = (
                        PREDICTIONS_DIR
                        / (
                            f"{model_key}_"
                            f"{feature_key}_"
                            f"logistic_seed_{seed}_"
                            f"test_predictions.csv"
                        )
                    )

                    logistic_prediction_df.to_csv(
                        logistic_prediction_path,
                        index=False,
                    )

                    del logistic_prediction_df


            except Exception as exc:

                print(
                    f"[{model_key} / {feature_key} / "
                    f"logistic / seed={seed}] failed: "
                    f"{type(exc).__name__}: {exc}"
                )


                all_rows.append(
                    {
                        "model":
                            model_key,

                        "representation":
                            feature_key,

                        "probe":
                            "logistic",

                        "seed":
                            seed,

                        "split":
                            "none",

                        "status":
                            "FAILED",

                        "error":
                            f"{type(exc).__name__}: {exc}",
                    }
                )


            # ====================================================
            # MLP
            # ====================================================

            if not HAS_EXPERIMENT_CONFIGS:

                print(
                    "MLP skipped: EXPERIMENT_CONFIGS is unavailable."
                )


                continue


            best_cfg = None
            best_model = None
            best_info = None


            # ----------------------------------------------------
            # Validation-only configuration selection
            # ----------------------------------------------------

            for cfg in tqdm(
                EXPERIMENT_CONFIGS,
                total=len(EXPERIMENT_CONFIGS),
                desc=f"{model_key}/{feature_key}/seed={seed} MLP configs",
                unit="config",
                leave=False,
            ):

                try:

                    mlp_model, info = (
                        fit_mlp_probe(
                            Xtr_s,
                            ytr,
                            Xva_s,
                            yva,
                            cfg,
                            seed,
                        )
                    )


                    candidate_score = info.get("val_auroc", np.nan)

                    all_rows.append({
                        "model": model_key,
                        "representation": feature_key,
                        "probe": "mlp",
                        "seed": seed,
                        "split": "validation_sweep",
                        "status": "COMPLETED" if np.isfinite(candidate_score) else "UNUSABLE",
                        "config_name": cfg.get("name"),
                        "hidden1": cfg.get("hidden1"),
                        "hidden2": cfg.get("hidden2"),
                        "hidden3": cfg.get("hidden3"),
                        "lr": cfg.get("lr"),
                        "weight_decay": cfg.get("weight_decay"),
                        "dropout": cfg.get("dropout"),
                        "epochs": cfg.get("epochs"),
                        "batch_size": cfg.get("batch_size"),
                        "val_auroc": candidate_score,
                        "selection_metric": "validation AUROC",
                    })


                    if not np.isfinite(
                        candidate_score
                    ):

                        print(
                            f"MLP config {cfg.get('name', 'unnamed')} "
                            "returned invalid validation AUROC; skipped."
                        )


                        continue


                    if (
                        best_info is None
                        or candidate_score
                        > best_info[
                            "val_auroc"
                        ]
                    ):

                        best_cfg = cfg
                        best_model = mlp_model
                        best_info = info


                except (
                    RuntimeError,
                    ValueError,
                ) as exc:

                    print(
                        f"MLP config skipped for "
                        f"{feature_key}, seed={seed}: "
                        f"{type(exc).__name__}: {exc}"
                    )


                    if torch.cuda.is_available():

                        torch.cuda.empty_cache()


                    gc.collect()


            # ----------------------------------------------------
            # No valid MLP configuration
            # ----------------------------------------------------

            if (
                best_model is None
                or best_cfg is None
                or best_info is None
            ):

                print(
                    f"No valid MLP configuration for "
                    f"{feature_key}, seed={seed}."
                )


                continue


            # ----------------------------------------------------
            # Save validation result for selected MLP
            # ----------------------------------------------------

            mlp_val_prob = get_probe_probabilities(
                best_model,
                Xva_s,
            )
            mlp_val_threshold, mlp_threshold_rule = select_validation_threshold(
                yva,
                mlp_val_prob,
            )


            mlp_val_metrics = safe_binary_metrics(
                yva,
                mlp_val_prob,
                threshold=mlp_val_threshold,
            )


            # Release the validation-selected model before allocating the
            # final refit model. This avoids keeping two MLPs resident.
            del best_model
            gc.collect()


            all_rows.append(
                {
                    "model":
                        model_key,

                    "representation":
                        feature_key,

                    "probe":
                        "mlp",

                    "seed":
                        seed,

                    "split":
                        "validation",

                    "status":
                        "COMPLETED",

                    "selected_config": best_cfg["name"],
                    "selected_epoch": best_info.get("epoch", np.nan),
                    "selected": True,
                    "threshold_rule": mlp_threshold_rule,
                    "hidden1": best_cfg["hidden1"],
                    "hidden2": best_cfg["hidden2"],
                    "hidden3": best_cfg["hidden3"],
                    "lr": best_cfg["lr"],
                    "weight_decay": best_cfg["weight_decay"],
                    "dropout": best_cfg["dropout"],
                    "weighting_mode": best_info.get("weighting", {}).get("mode"),
                    **mlp_val_metrics,
                }
            )


            # ----------------------------------------------------
            # Refit on train + validation
            # ----------------------------------------------------

            # Final MLP refit uses all allowed train + validation data to
            # estimate normalization statistics. Test remains isolated.
            Xfit_raw = np.vstack(
                [
                    Xtr,
                    Xva,
                ]
            )

            yfit = np.concatenate(
                [
                    ytr,
                    yva,
                ]
            )

            (
                Xfit,
                _unused_val_refit_mlp,
                Xte_refit,
                refit_mean_mlp,
                refit_std_mlp,
            ) = standardize_train_only(
                Xfit_raw,
                Xfit_raw,
                Xte,
            )


            try:

                refit_epochs = int(
                    best_info.get(
                        "epoch",
                        best_cfg.get(
                            "epochs",
                            1,
                        ),
                    )
                )


                refit_epochs = max(
                    1,
                    refit_epochs,
                )


                refit_model, refit_weighting = fit_mlp_probe_fixed_epochs(
                    Xfit,
                    yfit,
                    best_cfg,
                    seed,
                    epochs=refit_epochs,
                )


                te_prob = (
                    get_probe_probabilities(
                        refit_model,
                        Xte_refit,
                    )
                )


                test_metrics = safe_binary_metrics(
                    yte,
                    te_prob,
                    threshold=mlp_val_threshold,
                )


                if (
                    "expected_calibration_error"
                    in globals()
                ):

                    ece, calibration_df = (
                        expected_calibration_error(
                            yte,
                            te_prob,
                            n_bins=10,
                        )
                    )

                    test_metrics[
                        "ece"
                    ] = ece

                else:

                    calibration_df = pd.DataFrame()


                all_rows.append(
                    {
                        "model":
                            model_key,

                        "representation":
                            feature_key,

                        "probe":
                            "mlp",

                        "seed":
                            seed,

                        "split":
                            "test",

                        "status":
                            "COMPLETED",

                        "selected_config": best_cfg["name"],
                        "selected_epoch": refit_epochs,
                        "selected": True,
                        "threshold_rule": mlp_threshold_rule,
                        "hidden1": best_cfg["hidden1"],
                        "hidden2": best_cfg["hidden2"],
                        "hidden3": best_cfg["hidden3"],
                        "lr": best_cfg["lr"],
                        "weight_decay": best_cfg["weight_decay"],
                        "dropout": best_cfg["dropout"],
                        "weighting_mode": refit_weighting["mode"],

                        **test_metrics,
                    }
                )


                # ------------------------------------------------
                # Save test predictions
                # ------------------------------------------------

                prediction_df = pd.DataFrame(
                    {
                        "question_id":
                            test[
                                "question_id"
                            ]
                            .astype(str)
                            .to_numpy(),

                        "image_name":
                            (
                                test[
                                    "image_name"
                                ]
                                .astype(str)
                                .to_numpy()
                                if "image_name"
                                in test.columns
                                else
                                ""
                            ),

                        "label":
                            yte,

                        "probability": te_prob,
                        "threshold": float(mlp_val_threshold),
                        "prediction": (te_prob >= float(mlp_val_threshold)).astype(int),

                        "model":
                            model_key,

                        "representation":
                            feature_key,

                        "probe":
                            "mlp",

                        "seed":
                            seed,

                        "selected_config":
                            best_cfg["name"],

                        "selected": True,
                        "threshold_rule": mlp_threshold_rule,
                        "hidden1": best_cfg["hidden1"],
                        "hidden2": best_cfg["hidden2"],
                        "hidden3": best_cfg["hidden3"],
                        "lr": best_cfg["lr"],
                        "weight_decay": best_cfg["weight_decay"],
                        "dropout": best_cfg["dropout"],
                        "epochs": best_info["epoch"],
                        "weighting_mode": refit_weighting["mode"],

                    }
                )


                prediction_path = (
                    PREDICTIONS_DIR
                    / (
                        f"{model_key}_"
                        f"{feature_key}_"
                        f"mlp_seed_{seed}_"
                        f"test_predictions.csv"
                    )
                )


                prediction_df.to_csv(
                    prediction_path,
                    index=False,
                )


                # ------------------------------------------------
                # Calibration output
                # ------------------------------------------------

                if not calibration_df.empty:

                    calibration_path = (
                        PREDICTIONS_DIR
                        / (
                            f"{model_key}_"
                            f"{feature_key}_"
                            f"mlp_seed_{seed}_"
                            f"calibration.csv"
                        )
                    )


                    calibration_df.to_csv(
                        calibration_path,
                        index=False,
                    )


            except Exception as exc:

                print(
                    f"[{model_key} / {feature_key} / "
                    f"mlp / seed={seed}] refit/test failed: "
                    f"{type(exc).__name__}: {exc}"
                )


                all_rows.append(
                    {
                        "model":
                            model_key,

                        "representation":
                            feature_key,

                        "probe":
                            "mlp",

                        "seed":
                            seed,

                        "split":
                            "test",

                        "status":
                            "FAILED",

                        "error":
                            f"{type(exc).__name__}: {exc}",
                    }
                )


            # ------------------------------------------------
            # Free the selected MLP before next seed
            # ------------------------------------------------

            try:

                del best_model

                del refit_model

            except Exception:

                pass


            if torch.cuda.is_available():

                torch.cuda.empty_cache()


            gc.collect()


        # Release this representation before loading the next one.
        # These are local variables, so they must be deleted directly rather
        # than through `globals()`.
        try:
            del Xtr, Xva, Xte
        except NameError:
            pass

        try:
            del Xtr_s, Xva_s, Xte_s
        except NameError:
            pass

        try:
            del train_mean, train_std
        except NameError:
            pass

        try:
            del Xfit_logistic, yfit_logistic
        except NameError:
            pass

        try:
            del Xfit, yfit
        except NameError:
            pass

        try:
            del logistic_model, final_logistic
        except NameError:
            pass

        gc.collect()


    # --------------------------------------------------------
    # Save model-level result table
    # --------------------------------------------------------

    result_df = pd.DataFrame(
        all_rows
    )


    result_path = (
        TABLES_DIR
        / f"{model_key}_probe_results.csv"
    )


    result_df.to_csv(result_path, index=False)

    sweep_df = result_df[
        (result_df.get("split", pd.Series(index=result_df.index, dtype=object)) == "validation_sweep")
        & (result_df.get("probe", pd.Series(index=result_df.index, dtype=object)) == "mlp")
    ].copy()
    if not sweep_df.empty:
        sweep_path = TABLES_DIR / f"{model_key}_hyperparameter_sweep.csv"
        sweep_df.to_csv(sweep_path, index=False)


    print(
        "\n"
        + "-" * 82
    )


    print(
        f"{model_key} probe-results file:"
    )


    print(
        result_path
    )


    if result_df.empty:

        print(
            "No supervised probe results were produced."
        )

    else:

        print(
            "Result rows:",
            len(result_df)
        )


        if "status" in result_df.columns:

            print(
                "Status counts:",
                result_df[
                    "status"
                ]
                .value_counts(
                    dropna=False
                )
                .to_dict()
            )


    print(
        "-" * 82
    )


    return result_df


# ------------------------------------------------------------
# 12. Execute all active models
# ------------------------------------------------------------

probe_results = {}

PROBE_TRAINING_STATUS = {}


for model_key in tqdm(
    ACTIVE_MODELS,
    total=len(ACTIVE_MODELS),
    desc="Supervised probe models",
    unit="model",
):

    print(
        "\n"
        + "#" * 82
    )


    print(
        f"STARTING PROBE STAGE: {model_key}"
    )


    print(
        "#" * 82
    )


    try:

        result_df = (
            train_and_evaluate_model(
                model_key
            )
        )


        probe_results[
            model_key
        ] = result_df


        if result_df.empty:

            PROBE_TRAINING_STATUS[
                model_key
            ] = "NO_RESULTS"


        elif (
            "status"
            in result_df.columns
            and (
                result_df[
                    "status"
                ]
                == "BLOCKED"
            ).all()
        ):

            PROBE_TRAINING_STATUS[
                model_key
            ] = "BLOCKED"


        else:

            PROBE_TRAINING_STATUS[
                model_key
            ] = "COMPLETED"


    except Exception as exc:

        PROBE_TRAINING_STATUS[
            model_key
        ] = (
            f"FAILED — "
            f"{type(exc).__name__}: {exc}"
        )


        print(
            "\n"
            + "=" * 82
        )


        print(
            f"[{model_key}] PROBE STAGE FAILED"
        )


        print(
            "Exception type:",
            type(exc).__name__
        )


        print(
            "Exception:",
            str(exc)
        )


        print(
            "=" * 82
        )


        # A genuine failure should remain visible.
        raise


