# ------------------------------------------------------------
# 4. Filename-safe helper
# ------------------------------------------------------------

def safe_filename_component(
    value,
) -> str:
    """
    Convert model/representation names into safe filename components.
    """

    text = str(
        value
    ).strip()


    text = text.replace(
        "/",
        "_",
    )


    text = text.replace(
        "\\",
        "_",
    )


    text = text.replace(
        " ",
        "_",
    )


    text = text.replace(
        ":",
        "_",
    )


    return text


