# ------------------------------------------------------------
# 9. Confusion matrix
# ------------------------------------------------------------

def plot_confusion_matrix(
    record,
):
    """
    Plot a confusion matrix using the threshold stored with the test
    predictions. The threshold was selected on validation only.
    """

    y = record[
        "y"
    ]


    probability = record[
        "probability"
    ]


    threshold = float(record.get("threshold", 0.5))
    prediction = (probability >= threshold).astype(np.int64)


    cm = (
        skmetrics.confusion_matrix(
            y,
            prediction,
            labels=[
                0,
                1,
            ],
        )
    )


    model_name = safe_filename_component(
        record[
            "model"
        ]
    )


    representation_name = (
        safe_filename_component(
            record[
                "representation"
            ]
        )
    )


    probe_name = safe_filename_component(
        record[
            "probe"
        ]
    )


    seed_text = (
        f"_seed_{record['seed']}"
        if record["seed"] is not None
        else ""
    )


    output_path = (
        FIGURES_DIR
        / (
            f"confusion_matrix_"
            f"{model_name}_"
            f"{representation_name}_"
            f"{probe_name}"
            f"{seed_text}.png"
        )
    )


    plt.figure(
        figsize=(
            5.5,
            4.8,
        )
    )


    # Use matplotlib directly rather than requiring seaborn.
    image = plt.imshow(
        cm,
        interpolation="nearest",
    )


    plt.colorbar(
        image,
        fraction=0.046,
        pad=0.04,
    )


    plt.xticks(
        [0, 1],
        [
            "non-hallucination",
            "hallucination",
        ],
        rotation=20,
        ha="right",
    )


    plt.yticks(
        [0, 1],
        [
            "non-hallucination",
            "hallucination",
        ],
    )


    plt.xlabel(
        "Predicted"
    )


    plt.ylabel(
        "Actual"
    )


    plt.title(
        "Confusion Matrix\n"
        f"{record['model']} / "
        f"{record['representation']} / "
        f"{record['probe']}"
    )


    # Annotate cells.
    threshold = (
        cm.max()
        / 2.0
        if cm.size
        else 0.0
    )


    for i in range(
        cm.shape[0]
    ):

        for j in range(
            cm.shape[1]
        ):

            plt.text(
                j,
                i,
                str(
                    cm[i, j]
                ),
                ha="center",
                va="center",
                color=(
                    "white"
                    if cm[i, j] > threshold
                    else "black"
                ),
                fontsize=12,
            )


    return save_prediction_figure(
        output_path
    )


# ------------------------------------------------------------
# 10. Calibration curve
# ------------------------------------------------------------

def calculate_calibration_points(
    y,
    probability,
    n_bins: int = 10,
):
    """
    Compute empirical confidence and observed frequency for equal-width
    probability bins.
    """

    y = np.asarray(
        y,
        dtype=np.int64,
    )


    probability = np.asarray(
        probability,
        dtype=np.float64,
    )


    bins = np.linspace(
        0.0,
        1.0,
        n_bins + 1,
    )


    confidence = []
    observed_frequency = []
    counts = []


    for index in range(
        n_bins
    ):

        lower = bins[
            index
        ]


        upper = bins[
            index + 1
        ]


        if index == n_bins - 1:

            mask = (
                (probability >= lower)
                & (probability <= upper)
            )

        else:

            mask = (
                (probability >= lower)
                & (probability < upper)
            )


        if not np.any(
            mask
        ):

            continue


        confidence.append(
            float(
                probability[
                    mask
                ].mean()
            )
        )


        observed_frequency.append(
            float(
                y[
                    mask
                ].mean()
            )
        )


        counts.append(
            int(
                mask.sum()
            )
        )


    return (
        np.asarray(
            confidence,
            dtype=float,
        ),
        np.asarray(
            observed_frequency,
            dtype=float,
        ),
        np.asarray(
            counts,
            dtype=int,
        ),
    )


def plot_calibration_curve(
    record,
):
    """
    Plot empirical calibration using 10 equal-width probability bins.
    """

    y = record[
        "y"
    ]


    probability = record[
        "probability"
    ]


    (
        confidence,
        observed,
        counts,
    ) = calculate_calibration_points(
        y,
        probability,
        n_bins=10,
    )


    model_name = safe_filename_component(
        record[
            "model"
        ]
    )


    representation_name = (
        safe_filename_component(
            record[
                "representation"
            ]
        )
    )


    probe_name = safe_filename_component(
        record[
            "probe"
        ]
    )


    seed_text = (
        f"_seed_{record['seed']}"
        if record["seed"] is not None
        else ""
    )


    output_path = (
        FIGURES_DIR
        / (
            f"calibration_"
            f"{model_name}_"
            f"{representation_name}_"
            f"{probe_name}"
            f"{seed_text}.png"
        )
    )


    plt.figure(
        figsize=(
            6.5,
            5.5,
        )
    )


    # Perfect calibration reference.
    plt.plot(
        [0, 1],
        [0, 1],
        linestyle="--",
        linewidth=1.5,
        label="Perfect calibration",
    )


    if len(
        confidence
    ) > 0:

        plt.plot(
            confidence,
            observed,
            marker="o",
            linewidth=2,
            label="Model",
        )


    plt.xlabel(
        "Mean predicted probability"
    )


    plt.ylabel(
        "Observed frequency"
    )


    plt.title(
        "Calibration Curve\n"
        f"{record['model']} / "
        f"{record['representation']} / "
        f"{record['probe']}"
    )


    plt.xlim(
        0,
        1,
    )


    plt.ylim(
        0,
        1,
    )


    plt.legend(
        loc="best"
    )


    return save_prediction_figure(
        output_path
    )


